out<-witness;work<-769;
i<-0;work<-work+1;work<-work+2;
while(i<768){
 out.[i]<-W16.zero;work<-work+2;
 i<-i+1;work<-work+2;work<-work+2;
}
work<-work+2305;return(out,work);

